import sys
import subprocess
import psycopg2

DB_CONFIG = {
    ''host'': ''172.17.0.1'',
    ''port'': ''5432'',
    ''user'': ''postgres'',
    ''password'': ''password'',
    ''dbname'': ''postgres''
}

def run_query(target):
    conn = psycopg2.connect(**DB_CONFIG)
    conn.autocommit = True
    cur = conn.cursor()
    try:
        if target.endswith(''.sql''):
            with open(target, ''r'') as f:
                sql = f.read()
        else:
            sql = target
        cur.execute(sql)
        if cur.description:
            columns = [desc[0] for desc in cur.description]
            rows = cur.fetchall()
            print(' | '.join(columns))
            for row in rows:
                print(' | '.join(map(str, row)))
        else:
            print('Query executed successfully.')
    except Exception as e:
        print(f''Error: {e}'')
        sys.exit(1)
    finally:
        cur.close()
        conn.close()

if __name__ == ''__main__'':
    if len(sys.argv) < 2:
        print('Usage: python run_db.py <query_or_file_path>')
        sys.exit(1)
    run_query(sys.argv[1])\n' AS script_content;

